x		CTempMutex;	typedef TFracThread::CWhileSynchronized	CWhileSynchronized;	CRectStack(long numberOfRects);		// Initialize a new array with initialNumberOfRects rects.	~CRectStack();		// Free the array.	//------------------------------------------------------------------------------------	// Array manipulation primitives	//------------------------------------------------------------------------------------	long GetSize()	{ return fSize; }		// Returns the ACTUAL number of elements in the array.	void DeleteAll()	{ fSize = 0; }		// Remove all Rects from the stack. The stack is left empty.	void PushRect(const CRect_AC& theRect);		// Takes the CRect_AC you pass it, and pushes it on the stack.	bool PopRect(CRect_AC& theRect);		// Returns the first CRect_AC on the stack. That CRect_AC is then removed from		// the stack.	//------------------------------------------------------------------------------------	// Misc. functions	//------------------------------------------------------------------------------------	bool IsFull()	{ return (fSize >= fAllocatedSize); }		// Test if this array is full or not.	bool IsEmpty();		// Test if this array is empty or not.	void DoRead(short aRefNum, bool forPrinting);		// Read the stack size and data from the file.	void DoWrite(short aRefNum, bool makingCopy);		// Write the stack size and data to the file.  protected:	long fSize;									// number of elements ACTUALLY in the                                                // array, from 0 to the limit of memory	long fAllocatedSize;						// Number of elements for which storage is                                                // ALLOCATED#if qTuneRectStack	long fHighWaterMark;						// For tuning#endif	CRect_AC *fData;							// Pointer to CRect_AC storage array	CTempMutex	fLock;};//----------------------------------------------------------------------------------------// CRectQueue//----------------------------------------------------------------------------------------class CRectQueue{	//------------------------------------------------------------------------------------	// Creation/ Destruction Methods	//------------------------------------------------------------------------------------  public:	typedef TFracThread::CMutex			CMutex;	typedef TFracThread::CSemaphore		CSemaphore;	typedef TFracThread::CTempMutex		CTempMutex;	typedef TFracThread::CTempSemaphore	CTempSemaphore;	typedef TFracThread::CWhileSynchronized	CWhileSynchronized;	CRectQueue(long numberOfRects);		// Initialize a new queue with initialNumberOfRects rects.	~CRectQueue();		// Free the queue.	//------------------------------------------------------------------------------------	// Array manipulation primitives	//------------------------------------------------------------------------------------	long GetSize()	{ return fSize; }		// Returns the ACTUAL number of elements in the queue.	void DeleteAll()	{ fSize = fHead = fTail = 0; }		// Remove all Rects from the queue. The queue is left empty.	void PushRect(const CRect_AC& theRect);		// Takes the CRect_AC you pass it, and appends it to the queue.	void PushRectSync(const CRect_AC& theRect);		// Wait if the queue is full, then push the CRect_AC into it.	void AddRect(const CRect_AC& theRect);		// Takes the CRect_AC you pass it, and tries to add it to the last CRect_AC in		// the queue.  If it can't be added, it is just appended to the queue.	void AddRectSync(const CRect_AC& theRect);		// Wait if the queue is full, then add the CRect_AC into it.	void PopRect(CRect_AC& theRect);		// Returns the first CRect_AC in the queue. That CRect_AC is then removed from		// the queue.	//------------------------------------------------------------------------------------	// Misc. functions	//------------------------------------------------------------------------------------	bool IsFull()	{ return (fSize >= fAllocatedSize); }		// Test if this queue is full or not.	bool IsEmpty()	{ return (fSize <= 0); }		// Test if this queue is empty or not.  protected:	long fSize;									// number of elements ACTUALLY in the                                                // array, from 0 to the limit of memory	long fAllocatedSize;						// Number of elements for which storage is                                                // ALLOCATED#if qTuneRectStack	long fHighWaterMark;						// For tuning#endif	long fHead;									// index of first element in the queue	long fTail;									// index of next free slot in the queue												// (1 + index of last element)	CRect_AC *fData;							// Pointer to CRect_AC storage array	CTempMutex		fLock;	CTempSemaphore	fSpaceAvailable;};#endif // __URECTSTACK__